/*
 * Hand-written config.h for building libsmb2 on Windows with a mingw-w64
 * toolchain (Zig's bundled libc).  Normally generated by CMake; this file has
 * the same effect for the feature set we support: TCP sockets, no Kerberos, no
 * OpenSSL (libsmb2's own AES/MD4/HMAC implementations are used instead).
 */
#ifndef LIBSMB2_WIN32_CONFIG_H
#define LIBSMB2_WIN32_CONFIG_H

#define HAVE_STDINT_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_STRINGS_H 1
#define HAVE_MEMORY_H 1
#define HAVE_UNISTD_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TIME_H 1
#define HAVE_SYS_SOCKET_H 1
#define HAVE_POLL_H 1
#define HAVE_SOCKADDR_STORAGE 1
#define STDC_HEADERS 1

#endif /* LIBSMB2_WIN32_CONFIG_H */
